"""Real JEE Main questions — Physics Unit 2: Kinematics. Our own solutions; chk re-solves each one numerically —
projectiles by stepping the motion in small time steps, 1-D motion by integrating v(t) or a(x), river crossings
by vector addition. Skipped: graph items whose statements were cut off in the paper scan."""
import math
from common import new_registry, pick, near, verify
P, add = new_registry()
g = 10.0
def fly(u, th_deg, gg=9.8, dt=1e-4):   # numerical projectile: returns (T, H, R)
    th = math.radians(th_deg); vx, vy = u * math.cos(th), u * math.sin(th); x = y = t = 0.0; H = 0.0
    while True:
        vy -= gg * dt; x += vx * dt; y += vy * dt; t += dt; H = max(H, y)
        if y < 0: return t, H, x
def integ(f, a, b, n=20000):
    h = (b - a) / n; return sum(f(a + (i + 0.5) * h) for i in range(n)) * h

